import React, { useState } from 'react';
import { useAuth } from '../../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import './AuthForms.css';

const LoginForm: React.FC = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setIsLoading(true);

    try {
      console.log(`🔄 Login attempt: ${username}`);
      const user = await login(username, password);
      console.log('✅ Login successful, redirecting...');
      
      // Перенаправляем на главную страницу
      navigate('/');
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Login failed';
      setError(errorMessage);
      console.error('❌ Login error:', errorMessage);
    } finally {
      setIsLoading(false);
    }
  };

  const handleUseDemo = (demoUser: string) => {
    if (demoUser === 'admin') {
      setUsername('admin');
      setPassword('secret123');
    } else if (demoUser === 'user') {
      setUsername('user');
      setPassword('secret123');
    }
  };

  return (
    <div className="auth-container">
      <form className="auth-form" onSubmit={handleSubmit}>
        <h2>Вход в систему</h2>
        <p className="auth-subtitle">Используйте PostgreSQL аутентификацию</p>
        
        {error && <div className="error-message">{error}</div>}

        <div className="form-group">
          <label htmlFor="username">Имя пользователя:</label>
          <input
            type="text"
            id="username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            required
            disabled={isLoading}
            placeholder="admin или user"
            autoComplete="username"
          />
        </div>

        <div className="form-group">
          <label htmlFor="password">Пароль:</label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            disabled={isLoading}
            placeholder="secret123"
            autoComplete="current-password"
          />
        </div>

        <button type="submit" disabled={isLoading} className="auth-button primary">
          {isLoading ? 'Вход...' : 'Войти'}
        </button>

        <div className="auth-links">
          <p>Нет аккаунта? <a href="/register">Зарегистрироваться</a></p>
        </div>

        <div className="demo-section">
          <h4>📋 Демо аккаунты (PostgreSQL):</h4>
          <div className="demo-buttons">
            <button 
              type="button" 
              onClick={() => handleUseDemo('admin')}
              className="demo-button"
            >
              Использовать admin
            </button>
            <button 
              type="button" 
              onClick={() => handleUseDemo('user')}
              className="demo-button"
            >
              Использовать user
            </button>
          </div>
          <div className="demo-credentials">
            <p><strong>admin</strong> / secret123</p>
            <p><strong>user</strong> / secret123</p>
          </div>
          <div className="backend-check">
            <p className="backend-status" id="backend-status">
              🔄 Проверка подключения к серверу...
            </p>
          </div>
        </div>

        <div className="system-info">
          <p className="info-note">
            🔐 <strong>PostgreSQL Authentication</strong><br />
            Storage: MinIO для файлов<br />
            Database: PostgreSQL для пользователей
          </p>
        </div>
      </form>
    </div>
  );
};

export default LoginForm;
